B.a4O=new A.li("intro_1.jpg",1.05,1.18,B.fK,B.fJ,B.OR)
B.Rh=new A.a2(B.D,["Gente... olhem pra cima! O sol... est\xe1 sumindo!","Guys... look up! The sun... is disappearing!","Chicos... \xa1miren arriba! El sol... \xa1est\xe1 desapareciendo!"],t.w)
B.a4G=new A.dT("luna",B.Rh)
B.Rc=new A.a2(B.D,["Que coisa gigante \xe9 aquela?! Parece um castelo voando!","What is that giant thing?! It looks like a flying castle!","\xbf\xa1Qu\xe9 es esa cosa gigante!? \xa1Parece un castillo volando!"],t.w)
B.a4H=new A.dT("mira",B.Rc)
B.QY=new A.a2(B.D,["Durante o eclipse, uma fortaleza sombria surgiu no c\xe9u: a Cidadela Eclipse.","During the eclipse, a dark fortress rose in the sky: the Eclipse Citadel.","Durante el eclipse, una fortaleza oscura apareci\xf3 en el cielo: la Ciudadela Eclipse."],t.w)
B.a4L=new A.dT(null,B.QY)
