B.a4R=new A.li("intro_2.jpg",1.05,1.18,B.cw,B.b6,B.MI)
B.R4=new A.a2(B.D,["Ha ha ha ha! Povo de Nova City... a energia do N\xfacleo Nova agora pertence a MIM!","Ha ha ha ha! People of Nova City... the energy of the Nova Core now belongs to ME!","\xa1Ja ja ja ja! Pueblo de Nova City... \xa1la energ\xeda del N\xfacleo Nova ahora me pertenece a M\xcd!"],t.w)
B.a4y=new A.dT("emperor",B.R4)
B.R6=new A.a2(B.D,["Meus nove chefes v\xe3o guard\xe1-la pelo mundo inteiro. E voc\xeas, heroizinhos... v\xe3o passar uma temporada nas minhas c\xe1psulas!","My nine bosses will guard it all over the world. And you, little heroes... will spend some time in my capsules!","Mis nueve jefes la guardar\xe1n por todo el mundo. Y ustedes, hero\xedtos... \xa1pasar\xe1n una temporada en mis c\xe1psulas!"],t.w)
B.a4z=new A.dT("emperor",B.R6)
